// 간선을 가중치 오름차순으로 정렬해 차례로 본다 (find, unite는 유니온 파인드)
sort(edges.begin(), edges.end());              // (w, u, v)
long long total = 0; int cnt = 0;
for (auto [w, u, v] : edges) {
    if (cnt == n - 1) break;                   // 간선 n - 1개를 다 골랐다
    if (unite(u, v)) { total += w; cnt++; }    // 사이클을 만들지 않으면 고른다
}

